/* Original BhashaHub teaching content. Reference scope is documented in docs/hsk1-grammar-course.md. */
const example = (chinese, pinyin, english) => ({ chinese, pinyin, english });
const exercise = (prompt, answer, explanation) => ({ prompt, answer, explanation });
const point = (id, title, pattern, explanation, examples, commonMistake, exercises) => ({ id, title, pattern, explanation, examples, commonMistake, exercises });
const unit = (number, title, objective, points, foundations = []) => ({ number, title, objective, estimatedMinutes: number < 3 ? 25 : 40, foundations, points });

const units = [
  unit(1, 'Pinyin, tones, and your first sentence', 'Recognize how Mandarin syllables work, distinguish tones, and identify a subject and a predicate.', [], [
    point('F01', 'Read a Mandarin syllable', 'initial + final + tone', 'Pinyin records pronunciation, not an English approximation. Many syllables begin with an initial consonant followed by a final containing a vowel. Some syllables have no written initial. Learn the sound of each spelling rather than reading it as English. A word may contain more than one syllable; each syllable has its own tone.', [example('你', 'nǐ', 'you'), example('好', 'hǎo', 'good')], 'Do not use English letter names to pronounce pinyin. The spelling q, for example, represents a Mandarin sound rather than the English letter name.', [exercise('In nǐ, identify the initial and final.', 'Initial: n. Final: i. The mark shows third tone.', 'The tone mark is placed over the vowel in this syllable.'), exercise('How many syllables are in lǎo shī?', 'Two: lǎo and shī.', 'One Chinese word can contain multiple syllables.')]),
    point('F02', 'Hear tones and the neutral tone', 'tone 1: high; tone 2: rising; tone 3: low/dipping; tone 4: falling', 'Tone belongs to the syllable and can distinguish words. Start by hearing and producing the four main tones, then practice the lighter neutral tone. In connected speech, a third tone is often low rather than a full dip and rise. Before another third tone, the first third tone is pronounced like a second tone; ordinary learning materials usually retain the original tone marks.', [example('妈妈', 'mā ma', 'mother'), example('你好', 'nǐ hǎo', 'hello; the first syllable is pronounced with a rising tone here')], 'Do not give a neutral syllable the same stress and duration as a full-tone syllable. Do not change the dictionary spelling of every third tone merely because connected pronunciation changes.', [exercise('Which syllable is neutral in mā ma?', 'The second ma.', 'It is shorter and lighter, with no numbered lexical tone in this transcription.'), exercise('How is the first syllable of nǐ hǎo normally pronounced?', 'Like ní, before the following third tone.', 'This is the third-tone change in connected speech.')]),
    point('F03', 'Find the sentence frame', 'subject + predicate; subject + verb + object', 'A subject tells us who or what the sentence is about. The predicate says something about it. A useful first pattern is subject–verb–object. Mandarin does not change a verb to match I, you, or they. Keep the frame stable while changing the person or the object.', [example('我喝水。', 'Wǒ hē shuǐ.', 'I drink water.'), example('她看书。', 'Tā kàn shū.', 'She reads a book.')], 'Do not move the object in front of the verb because that is natural in another language. Start with the neutral subject–verb–object order.', [exercise('Arrange: 水 / 我 / 喝', '我喝水。', '我 is the subject, 喝 the verb, and 水 the object.'), exercise('Change 我看书 to “He reads a book.”', '他看书。', 'Only the subject changes. 看 does not acquire a person ending.')]),
  ]),
  unit(2, 'Reading notation and useful sentence habits', 'Place tone marks, recognize neutral syllables, and use polite fixed expressions appropriately.', [], [
    point('F04', 'Place tone marks and read shortened finals', 'a first; otherwise o or e; in iu/ui mark the last vowel', 'A tone mark goes on a vowel, not on a consonant. In the combinations iu and ui it appears on the last written vowel. The spellings iu, ui, and un are shortened spellings in appropriate syllables: their full finals are iou, uei, and uen. The two dots of ü are omitted after j, q, and x, but retained where they distinguish sounds, as in nǚ.', [example('六', 'liù', 'six'), example('女儿', 'nǚ ér', 'daughter')], 'Do not pronounce the u after j, q, or x as an ordinary u just because the dots are not printed. It represents the ü sound in these syllables.', [exercise('Where does the tone mark go in liu with fourth tone?', 'liù', 'For iu, mark the last written vowel.'), exercise('Should the dots be retained in nǚ?', 'Yes: nǚ.', 'After n, ü is distinguished from u by its dots.')]),
    point('F05', 'Use short expressions as complete responses', '谢谢 → 不客气; 对不起 → 没关系', 'Some everyday expressions can stand alone because their purpose is clear from the situation. Use 谢谢 to thank someone and 不客气 to respond. Use 对不起 to apologize and 没关系 to reassure the speaker. Treat these as useful fixed expressions rather than trying to build every part from English word order.', [example('谢谢老师。', 'Xiè xie lǎo shī.', 'Thank you, teacher.'), example('没关系。', 'Méi guān xi.', 'It is all right.')], 'Do not answer an apology with 不客气 when you mean “It is all right.” The usual pairing here is 对不起 and 没关系.', [exercise('Respond politely to 谢谢.', '不客气。', 'This acknowledges thanks.'), exercise('Respond reassuringly to 对不起.', '没关系。', 'This tells the other person that the problem is not serious.')]),
    point('F06', 'Keep basic negation before the predicate', '不 + verb/adjective; 没有 + noun', 'A negative word normally comes before what it negates. 不 is used with ordinary habits, intentions, identity, and descriptions. 有 is negated with 没有 rather than 不有. Later lessons distinguish 没 before an action that has not happened. 不 is pronounced bú before a fourth-tone syllable, although its dictionary tone is bù.', [example('我不喝茶。', 'Wǒ bù hē chá.', 'I do not drink tea.'), example('我没有书。', 'Wǒ méi yǒu shū.', 'I do not have a book.')], 'Do not use 不有 for “do not have.” Do not put 不 after the main verb in an ordinary negative statement.', [exercise('Make 我是老师 negative.', '我不是老师。', '不 comes before 是.'), exercise('Correct: 我不有电脑。', '我没有电脑。', '有 takes 没有 as its ordinary negative form.')]),
  ]),
  unit(3, 'Names, identity, and yes/no questions', 'Ask what someone is called and check a statement with a yes/no question.', [
    point('G01', 'Ask what with 什么', 'subject + verb + 什么 (+ noun)', 'Put 什么 in the position of the information you want. The rest of the sentence keeps the order of a statement. In a name question, 什么 modifies 名字. A question word already makes the sentence a question, so a neutral question does not also need 吗.', [example('你叫什么名字？', 'Nǐ jiào shén me míng zi?', 'What is your name?'), example('你喝什么？', 'Nǐ hē shén me?', 'What do you drink?')], 'Avoid adding 吗 to an ordinary 什么 question. Do not move 什么 to the beginning just to imitate English question order.', [exercise('Complete: 你看___书？ (“What book are you reading?”)', '什么', '什么 replaces the missing description of 书.'), exercise('Translate: “What does she eat?”', '她吃什么？', 'The question word occupies the object position.')]),
    point('G02', 'Identify someone or something with 是', 'A + 是 + B; A + 不是 + B', 'Use 是 to connect a person or thing with an identifying noun or noun phrase. It can identify a job, a person, or a category. 是 does not change with the subject. Negate identity with 不是. Ordinary adjective descriptions usually use a different pattern, introduced in unit 6.', [example('他是医生。', 'Tā shì yī shēng.', 'He is a doctor.'), example('这不是我的杯子。', 'Zhè bú shì wǒ de bēi zi.', 'This is not my cup.')], 'Do not insert 是 before every adjective just because English uses “is.” Keep 是 for the identity pattern being learned here.', [exercise('Complete: 我___学生。', '是', '学生 is an identifying noun.'), exercise('Make 她是老师 negative.', '她不是老师。', 'Put 不 before 是; 不 is pronounced bú before shì.')]),
    point('G03', 'Turn a statement into a question with 吗', 'statement + 吗？', 'Add 吗 to a complete statement to ask whether it is true. Keep the subject, verb, and object in their statement positions. A natural short answer repeats the relevant predicate, positively or negatively. Mandarin does not require a separate English-style question auxiliary.', [example('你是学生吗？', 'Nǐ shì xué sheng ma?', 'Are you a student?'), example('你喝茶吗？', 'Nǐ hē chá ma?', 'Do you drink tea?')], 'Do not reverse 是 and the subject. A neutral 什么, 谁, or 哪儿 question normally does not take an additional 吗.', [exercise('Ask whether 他是医生 is true.', '他是医生吗？', 'Attach 吗 to the statement without changing its order.'), exercise('Answer 你是老师吗？ negatively.', '不是。 / 我不是老师。', 'The answer negates the identity predicate.')]),
  ]),
  unit(4, 'People, possession, and follow-up questions', 'Ask who or which, describe ownership, and return a question.', [
    point('G04', 'Choose between 谁 and 哪', '谁 = who; 哪 + measure word + noun = which ...', '谁 asks for a person and stays in the position occupied by that person. 哪 selects from a set of people or things. Before an ordinary counted noun, use the appropriate measure word after 哪. Do not confuse 哪, “which,” with 那, “that.”', [example('谁是你的老师？', 'Shéi shì nǐ de lǎo shī?', 'Who is your teacher?'), example('你看哪本书？', 'Nǐ kàn nǎ běn shū?', 'Which book are you reading?')], '哪 and 那 differ in tone and meaning. Use 哪本书 for “which book,” rather than a bare 哪书 in this beginner pattern.', [exercise('Ask “Who is he?”', '他是谁？', '谁 replaces the identifying person after 是.'), exercise('Complete “which cup”: 哪___杯子', '个', '个 is the measure word used with 杯子 here.')]),
    point('G05', 'Connect an owner and a noun with 的', 'owner + 的 + noun', 'Place the owner before 的 and the owned item after it. The owner can be a pronoun or a noun phrase. Mandarin has no separate change like “I” becoming “my”; 的 performs that linking job. Keep longer owner phrases together before 的.', [example('这是我的书。', 'Zhè shì wǒ de shū.', 'This is my book.'), example('那是老师的电脑。', 'Nà shì lǎo shī de diàn nǎo.', 'That is the teacher’s computer.')], 'Do not put the owner after the noun. Later, unit 12 explains why 的 can sometimes be omitted in close relationships.', [exercise('Build “her name.”', '她的名字', 'The owner 她 comes before 的 and 名字.'), exercise('Translate: “This is his cup.”', '这是他的杯子。', 'Use 他的 before 杯子.')]),
    point('G06', 'Return a question with 呢', 'known topic + 呢？', 'After a topic has been established, use a noun or pronoun plus 呢 to ask the corresponding question about another person or thing. The missing predicate is supplied by context. This is useful for “What about you?” but does not replace every possible question word.', [example('我是学生。你呢？', 'Wǒ shì xué sheng. Nǐ ne?', 'I am a student. What about you?'), example('我喝水。她呢？', 'Wǒ hē shuǐ. Tā ne?', 'I drink water. What about her?')], 'A bare 你呢 needs a recoverable topic. It does not independently mean “How are you?” in every situation.', [exercise('After 我是老师, ask the same question about him.', '他呢？', 'The established topic is identity or occupation.'), exercise('After 我喝茶, ask about the listener.', '你呢？', 'The listener understands that the omitted question concerns what they drink.')]),
  ]),
  unit(5, 'Numbers, family size, age, and change', 'Count to 99, ask small quantities and ages, and describe a newly relevant state.', [
    point('G07', 'Ask a small expected quantity with 几', '几 + measure word + noun', '几 asks for a number, usually when a relatively small answer is expected. It does not impose an absolute mathematical limit of nine. Retain the measure word before an ordinary counted noun. For family members, 口 is a conventional measure word.', [example('你家有几口人？', 'Nǐ jiā yǒu jǐ kǒu rén?', 'How many people are in your family?'), example('你有几本书？', 'Nǐ yǒu jǐ běn shū?', 'How many books do you have?')], 'Do not leave out the measure word in 几本书. Do not treat 几 as a rule that makes any answer above nine impossible.', [exercise('Complete: 你有___个杯子？', '几', 'The question asks how many cups there are.'), exercise('Answer 你家有几口人？ for three family members.', '我家有三口人。', 'Replace 几 with the number while retaining 口.')]),
    point('G08', 'Build numbers from zero to 99', '十 + ones; tens + 十 + ones', '十一 is eleven, 二十 is twenty, and 二十一 is twenty-one. In the teens, the initial one is normally not spoken: 十三, rather than 一十三. Read telephone numbers and calendar years differently; those digit-by-digit patterns come later. Learn 零 as zero even when it does not appear inside a particular two-digit number.', [example('十五', 'shí wǔ', 'fifteen'), example('四十八', 'sì shí bā', 'forty-eight')], 'Do not reverse the tens and ones. 十八 means eighteen, while 八十 means eighty.', [exercise('Write 32 in Chinese characters.', '三十二', 'Three tens followed by two.'), exercise('What number is 九十六?', '96', '九十 is ninety, followed by 六.')]),
    point('G09', 'Mark a newly relevant state with sentence-final 了', 'new state + 了', 'Sentence-final 了 can present a change or newly relevant situation. It is not simply a past-tense ending. In an age statement, it can announce that a child has now reached that age. A plain age statement without 了 can also be correct; the particle adds the perspective of change or current relevance.', [example('我女儿五岁了。', 'Wǒ nǚ ér wǔ suì le.', 'My daughter is five now.'), example('现在十点了。', 'Xiàn zài shí diǎn le.', 'It is ten o’clock now.')], 'Do not translate every past event with this sentence-final 了. Unit 14 introduces the related but different use of 了 after a completed action.', [exercise('Add a change-of-state reading to 他二十岁.', '他二十岁了。', 'Final 了 highlights reaching that age.'), exercise('Does 现在八点了 automatically mean “It was eight o’clock”?', 'No. It normally announces that it is now eight.', 'The particle marks a newly relevant state, not an automatic past tense.')]),
    point('G10', 'Ask someone’s age with 多大', 'person + 多大？; person + number + 岁', '多大 asks how old someone is in an appropriate context. Give an age with a number followed by 岁. The beginner age predicate does not require 是. 几岁 is especially common when asking about a young child; be considerate about asking adults their age.', [example('你今年多大？', 'Nǐ jīn nián duō dà?', 'How old are you this year?'), example('我今年十八岁。', 'Wǒ jīn nián shí bā suì.', 'I am eighteen this year.')], 'Do not add 个 before 岁 in this age pattern. 多大 is the established age question; it is not formed with 多少岁 as its only possible equivalent.', [exercise('Answer for a seven-year-old: 你今年多大？', '我今年七岁。', 'The age is number + 岁.'), exercise('Correct this beginner age phrase: 十八个岁.', '十八岁', '岁 directly follows the number.')]),
  ]),
  unit(6, 'Skills, descriptions, and methods', 'Describe a learned skill, make a basic adjective statement, and ask how to do something.', [
    point('G11', 'Describe a learned skill with 会', 'subject + 会 / 不会 + skill', '会 before a verb can mean that someone has learned how to do an activity. It is appropriate for language, swimming, or cooking skills. No “to” is inserted between 会 and the following verb. Negate this learned ability with 不会. Unit 10 contrasts 能, and unit 12 introduces another meaning of 会.', [example('我会写汉字。', 'Wǒ huì xiě Hàn zì.', 'I can write Chinese characters.'), example('他不会做饭。', 'Tā bú huì zuò fàn.', 'He does not know how to cook.')], 'Do not use 会 simply because English has “can.” Permission and current circumstances often call for 能 instead.', [exercise('Say “She knows how to speak Chinese.”', '她会说汉语。', '会 marks the learned skill.'), exercise('Make 我会写汉字 negative.', '我不会写汉字。', '不 comes before 会.')]),
    point('G12', 'Describe with an adjective predicate', 'subject + 很 + adjective; subject + 不 + adjective', 'Many Mandarin adjectives can directly form a predicate. In a neutral affirmative description, 很 often links the subject and adjective without a strongly stressed “very.” Do not automatically insert 是. Negatives can use 不 plus the adjective. 很 can still mean “very” when emphasized or in a suitable context.', [example('今天很热。', 'Jīn tiān hěn rè.', 'It is hot today.'), example('这个杯子不大。', 'Zhè ge bēi zi bú dà.', 'This cup is not big.')], 'Avoid the beginner error 今天是热. Do not assume every unstressed 很 must be translated as an emphatic “very.”', [exercise('Build a neutral description: 她 / 高兴.', '她很高兴。', 'An adjective can be the predicate, commonly with 很.'), exercise('Make 今天很冷 negative without keeping 很.', '今天不冷。', '不 directly negates the description.')]),
    point('G13', 'Ask how an action is done with 怎么', 'subject + 怎么 + verb (+ object)？', '怎么 before a verb asks about the method or way of doing an action. Keep the action after 怎么. At this stage, distinguish this method question from 怎么样, which asks about a condition or evaluation. Context can give 怎么 other readings, but the target here is “how.”', [example('这个字怎么写？', 'Zhè ge zì zěn me xiě?', 'How do you write this character?'), example('你怎么去学校？', 'Nǐ zěn me qù xué xiào?', 'How do you get to school?')], 'Do not use 怎么样 directly as a replacement for 怎么 in 这个字怎么写. The question concerns the action’s method.', [exercise('Ask how to read this character.', '这个字怎么读？', 'Put 怎么 before 读.'), exercise('Answer 你怎么去学校？ using a taxi.', '我坐出租车去学校。', 'The answer states the method of travel before the destination action.')]),
  ]),
  unit(7, 'Dates and purposeful actions', 'Give a short date, use noun predicates for age and dates, and say where you go to do something.', [
    point('G14', 'Give a month, date, and weekday', 'month + 月 + day + 号/日; 星期 + number', 'Mandarin dates proceed from larger units to smaller ones. In ordinary spoken dates, 号 is common for the day of the month; 日 is common in written dates. 星期一 through 星期六 cover Monday to Saturday. Sunday is 星期天 or 星期日. Ask the day of the month with 几号 and the weekday with 星期几.', [example('今天六月八号。', 'Jīn tiān liù yuè bā hào.', 'Today is June 8.'), example('明天星期三。', 'Míng tiān xīng qī sān.', 'Tomorrow is Wednesday.')], 'Do not reverse day and month. 星期八 is not Sunday.', [exercise('Say “September 12” as a spoken date.', '九月十二号', 'Month precedes day.'), exercise('Ask “What day of the week is today?”', '今天星期几？', '星期几 asks for the weekday, not the day of the month.')]),
    point('G15', 'Use a noun or number phrase as a predicate', 'subject + age/date/time phrase', 'Some ordinary affirmative sentences about age, dates, days, and prices use a noun or number phrase directly as the predicate. This is a limited pattern, not permission to omit 是 from every identity sentence. 是 can appear for emphasis or correction in appropriate contexts, but is not required in these neutral beginner statements.', [example('今天星期五。', 'Jīn tiān xīng qī wǔ.', 'Today is Friday.'), example('我弟弟十岁。', 'Wǒ dì di shí suì.', 'My younger brother is ten.')], 'Do not generalize from 我十八岁 to an identity statement such as 我老师. For an ordinary job identification, say 我是老师.', [exercise('Give “Today is May 2” without 是.', '今天五月二号。', 'A date phrase can act as the predicate.'), exercise('Which needs 是 in a neutral identity statement: 我学生 or 我十八岁?', '我是学生。', '学生 is a job/status identity here; the age pattern is different.')]),
    point('G16', 'Go somewhere to do something', 'subject + 去 + place + activity', 'A series of verbs can express a purposeful sequence: going to a place in order to perform an activity there. Put the destination after 去, then state the intended activity. No English-style infinitive word is needed. Keep the destination attached to 去 so the sentence is easy to follow.', [example('我去商店买水果。', 'Wǒ qù shāng diàn mǎi shuǐ guǒ.', 'I am going to the shop to buy fruit.'), example('她去学校学汉语。', 'Tā qù xué xiào xué Hàn yǔ.', 'She goes to school to study Chinese.')], 'Do not insert 和 between 去商店 and 买水果 just to translate “go and buy.” They form a purposeful serial-verb sequence.', [exercise('Arrange: 买书 / 我 / 去 / 商店.', '我去商店买书。', 'Destination comes before the activity done there.'), exercise('Translate: “He goes to the restaurant to eat.”', '他去饭店吃饭。', '去饭店 is followed by the purpose 吃饭.')]),
  ]),
  unit(8, 'Wishes, quantities, and prices', 'Express what you would like, ask a quantity or price, and use basic measure words.', [
    point('G17', 'Express a wish or intention with 想', 'subject + 想 / 不想 + action', '想 before a verb can express wanting or intending to do something. It describes a wish rather than a guaranteed future event. Put the desired activity directly after 想. Negate this intention with 不想. 想 has other uses, such as thinking about someone, but this lesson focuses on wanting to do an action.', [example('我想喝水。', 'Wǒ xiǎng hē shuǐ.', 'I would like some water.'), example('她今天不想去学校。', 'Tā jīn tiān bù xiǎng qù xué xiào.', 'She does not want to go to school today.')], 'Do not use 想 as a universal future-tense marker. A future time expression can describe an action without 想.', [exercise('Say “We want to watch a film.”', '我们想看电影。', 'Place 想 before the intended activity.'), exercise('Negate 我想吃米饭.', '我不想吃米饭。', '不 negates the intention expressed by 想.')]),
    point('G18', 'Ask an amount with 多少', '多少 + (measure word) + noun; 多少钱', '多少 asks a quantity without the small-number expectation often associated with 几. A measure word can be omitted in some familiar 多少 questions, but it is also possible to retain one. 多少钱 is the everyday price question. The question word stays where the amount belongs rather than forcing English question order.', [example('这本书多少钱？', 'Zhè běn shū duō shao qián?', 'How much is this book?'), example('你有多少本书？', 'Nǐ yǒu duō shao běn shū?', 'How many books do you have?')], 'Do not confuse 多少 with 多大, the age question. Do not add 吗 to an ordinary 多少 question.', [exercise('Ask the price of this cup.', '这个杯子多少钱？', '多少钱 replaces the unknown price.'), exercise('Choose a question for an unrestricted quantity: 几 or 多少?', '多少', 'It does not suggest the same relatively small expected answer as 几.')]),
    point('G19', 'Count with 个 and 口', 'number + measure word + noun', 'Ordinary counted nouns usually need a measure word between the number and the noun. 个 is common, but not universal; learn the measure word with the noun. 口 is conventional for counting family members. Use 两 rather than 二 before 个 or 口 in these basic noun phrases. 二 remains normal inside numbers such as 二十.', [example('我有两个杯子。', 'Wǒ yǒu liǎng ge bēi zi.', 'I have two cups.'), example('我家有四口人。', 'Wǒ jiā yǒu sì kǒu rén.', 'There are four people in my family.')], 'Avoid 二个杯子 in this standard beginner pattern. Do not assume every noun takes 个: books, for example, commonly take 本.', [exercise('Complete “two students”: ___个学生.', '两', 'Use 两 before the measure word 个.'), exercise('Correct: 三人, when counting members of a family in this pattern.', '三口人', 'Retain the conventional measure word 口.')]),
    point('G20', 'Understand spoken money amounts', 'number + 块/元 (+ number + 毛/角)', '元 is the formal unit for Chinese currency; 块 is its common spoken counterpart. 角 is one tenth of a yuan and is often called 毛. A spoken amount such as 十块五 normally means ten yuan and five jiao, or 10.50 yuan. State the units clearly while learning. For the number two before 块, 两块 is the usual spoken form.', [example('这本书二十块钱。', 'Zhè běn shū èr shí kuài qián.', 'This book costs twenty yuan.'), example('这个杯子十块五毛。', 'Zhè ge bēi zi shí kuài wǔ máo.', 'This cup costs ten yuan fifty.')], 'Do not read 十块五 as 10.05 yuan. Five jiao is half a yuan; five fen would be five hundredths.', [exercise('How much is 八块五毛 in yuan?', '8.50 yuan.', 'Five jiao is 0.50 yuan.'), exercise('Say “two yuan” using 块.', '两块钱', '两 is common before the currency measure word 块.')]),
  ]),
  unit(9, 'Location and where an action happens', 'Say where people are, ask where something is, and place an activity in a location.', [
    point('G21', 'Locate someone or something with 在', 'subject + 在 + place', 'When 在 is the main verb, it tells us where a person or thing is. Put the location after 在. There is no need to add 是 before 在. Negate an ordinary location statement with 不在. The location can be a named place or an expression such as 家 or 学校.', [example('妈妈在家。', 'Mā ma zài jiā.', 'Mother is at home.'), example('老师不在学校。', 'Lǎo shī bú zài xué xiào.', 'The teacher is not at school.')], 'Do not say 妈妈是在家 when you simply mean a neutral location statement. 是 can add contrast in other contexts, but is not needed here.', [exercise('Translate: “The doctor is at the hospital.”', '医生在医院。', '在 is the main location verb.'), exercise('Make 他在家 negative.', '他不在家。', 'Use 不 before 在 for ordinary location negation.')]),
    point('G22', 'Ask where with 哪儿', 'subject + 在 + 哪儿？; 去 + 哪儿？', '哪儿 asks for a location and remains where the place expression would appear. 哪里 is another common form. The verb determines whether you are asking where someone is, where they go, or where an activity happens. Distinguish 哪儿, “where,” from 那儿, “there.”', [example('你的书在哪儿？', 'Nǐ de shū zài nǎr?', 'Where is your book?'), example('你明天去哪儿？', 'Nǐ míng tiān qù nǎr?', 'Where are you going tomorrow?')], 'Do not interchange 哪儿 and 那儿. An ordinary 哪儿 question does not need an additional 吗.', [exercise('Ask “Where is she?”', '她在哪儿？ / 她在哪里？', 'The question word replaces the place after 在.'), exercise('Change 他去北京 into a question about the destination.', '他去哪儿？', 'Replace 北京 with 哪儿 without moving the subject or verb.')]),
    point('G23', 'Locate an activity before its verb', 'subject + 在 + place + action', '在 plus a place can come before the main action to say where it happens. Here the main predicate includes another verb, unlike the simple location statement in G21. A useful beginner order is subject, time, place, action. Do not put the ordinary activity location after the object by copying English order.', [example('她在医院工作。', 'Tā zài yī yuàn gōng zuò.', 'She works at a hospital.'), example('我在家看书。', 'Wǒ zài jiā kàn shū.', 'I read at home.')], 'Avoid 我看书在家 for the neutral beginner sentence “I read at home.” Place 在家 before 看书.', [exercise('Arrange: 学汉语 / 我 / 在学校.', '我在学校学汉语。', 'The place phrase comes before the action.'), exercise('Ask where he works.', '他在哪儿工作？', '哪儿 replaces the place inside the 在 phrase.')]),
    point('G24', 'Use 呢 to ask after a person or thing', 'person/thing + 呢？ with a recoverable question', 'A short 呢 question can ask where an expected person or object is, when the situation makes that meaning clear. It can also add a wondering or follow-up tone to an explicit question. Context is essential: the same noun + 呢 pattern may ask about another topic instead. Use 在哪儿 when you need to make the location question explicit.', [example('我的杯子呢？', 'Wǒ de bēi zi ne?', 'Where is my cup?'), example('老师在哪儿呢？', 'Lǎo shī zài nǎr ne?', 'Where might the teacher be?')], 'Do not memorize 呢 as a word that always means “where.” The surrounding situation supplies the omitted question.', [exercise('You are looking for your book. Ask a short 呢 question.', '我的书呢？', 'The search situation makes the location meaning clear.'), exercise('Make the location meaning explicit in 你爸爸呢？', '你爸爸在哪儿？', '在哪儿 directly asks about location.')]),
  ]),
  unit(10, 'Existence, permission, and polite requests', 'Describe what exists, join nouns, and ask politely whether an action is possible.', [
    point('G25', 'Say what someone has or what exists', 'person + 有 + thing; place + 有 + thing', '有 expresses possession after a person and existence after a place. These frames answer different questions: a person frame tells us what someone has; a place frame tells us what is present there. Negate 有 with 没有. An existential 有 sentence introduces something at a place; a 在 sentence locates an already identified thing.', [example('我有一本书。', 'Wǒ yǒu yì běn shū.', 'I have a book.'), example('桌子上有一个杯子。', 'Zhuō zi shàng yǒu yí ge bēi zi.', 'There is a cup on the table.')], 'Do not use 不有. Keep the contrast between 桌子上有一个杯子, introducing a cup, and 杯子在桌子上, locating the cup.', [exercise('Negate 桌子上有书.', '桌子上没有书。', 'Use 没有 for the negative of 有.'), exercise('Say “There are three people at home.”', '家里有三个人。', 'A place expression comes before existential 有.')]),
    point('G26', 'Join people or things with 和', 'noun phrase + 和 + noun phrase', '和 joins nouns or noun phrases in a list. The combined phrase can be a subject or an object. In this beginner use, it is not a general connector between complete sentences or a replacement for every English “and.” To express that everyone in a combined subject does something, 都 may be added after the whole subject; that point is developed in unit 14.', [example('我和她是同学。', 'Wǒ hé tā shì tóng xué.', 'She and I are classmates.'), example('我买苹果和茶。', 'Wǒ mǎi píng guǒ hé chá.', 'I buy apples and tea.')], 'Do not connect two complete clauses by inserting 和 between them as if it were always the English sentence connector “and.”', [exercise('Join 我 and 老师 into one noun phrase.', '我和老师', '和 joins the two people.'), exercise('Correct the noun list 苹果、茶 by explicitly joining the two items.', '苹果和茶', 'The connector links the two nouns in the list.')]),
    point('G27', 'Express ability or permission with 能', 'subject + 能 / 不能 + action', '能 can describe whether circumstances, physical ability, or permission allow an action. A polite 能…吗 question asks whether doing something is possible or allowed. Contrast this with 会 for a learned skill. Someone may know how to do an activity but be unable to do it today because of circumstances.', [example('我能坐这儿吗？', 'Wǒ néng zuò zhèr ma?', 'May I sit here?'), example('我今天不能去学校。', 'Wǒ jīn tiān bù néng qù xué xiào.', 'I cannot go to school today.')], 'Do not choose 会 for every permission request just because English uses “can.” Consider whether the issue is learned skill or present possibility.', [exercise('Ask permission to drink this water.', '我能喝这杯水吗？', '能…吗 asks whether the action is allowed.'), exercise('Choose 会 or 能: you learned Chinese, but you cannot attend school today.', '会 for the learned language skill; 不能去学校 for today’s restriction.', 'The two modal verbs express different kinds of ability.')]),
    point('G28', 'Make a polite instruction with 请', '请 + action', '请 before a verb makes a request or invitation more polite. A short 请 sentence can omit the subject when the listener is clear. 请 does not by itself turn every sentence into a question; it is a polite request marker in this pattern. Keep the requested action immediately after it.', [example('请坐。', 'Qǐng zuò.', 'Please sit down.'), example('请喝茶。', 'Qǐng hē chá.', 'Please have some tea.')], 'Do not place 请 after the whole action as a direct imitation of English final “please.” Learn the beginner frame 请 + verb.', [exercise('Make “sit here” into a polite request.', '请坐这儿。', '请 comes before the requested action.'), exercise('Invite someone to look at this book.', '请看这本书。', '请 introduces the invitation to perform the action.')]),
  ]),
  unit(11, 'Clock time and scheduling', 'Tell the time, say when actions happen, and use 前 for before or ago.', [
    point('G29', 'Tell and ask the clock time', 'number + 点 + number + 分; 几点？', 'Use 点 after the hour and 分 after the minutes. Minutes after ten need their complete value; zero minutes can be omitted. Add 上午, 下午, or another suitable time-of-day expression when needed. 几点 asks the hour or general clock time, while 几点几分 can request more detail. Use 两点 for two o’clock.', [example('现在八点十分。', 'Xiàn zài bā diǎn shí fēn.', 'It is 8:10 now.'), example('现在下午两点。', 'Xiàn zài xià wǔ liǎng diǎn.', 'It is two in the afternoon now.')], 'Distinguish eight o’clock, 八点, from eight minutes, 八分钟. Use 两点 rather than 二点 for the ordinary spoken hour.', [exercise('Write 3:25 in Chinese.', '三点二十五分', 'The hour precedes 点 and the minutes precede 分.'), exercise('Ask the current time.', '现在几点？', '现在 sets the present context and 几点 asks for clock time.')]),
    point('G30', 'Put a time expression before the action', 'subject + time + action; time + subject + action', 'A time expression normally appears before the main verb. It can follow the subject or be placed at the beginning of the sentence. If both time and a place phrase modify the action, a useful neutral order is subject, time, place, action. Mandarin does not need to change the verb form simply because the time is tomorrow or yesterday.', [example('我明天去北京。', 'Wǒ míng tiān qù Běi jīng.', 'I am going to Beijing tomorrow.'), example('今天我在家学汉语。', 'Jīn tiān wǒ zài jiā xué Hàn yǔ.', 'Today I study Chinese at home.')], 'Avoid 我去北京明天 as the neutral scheduling pattern. Put 明天 before 去北京.', [exercise('Arrange: 看电影 / 我们 / 下午三点.', '我们下午三点看电影。 / 下午三点我们看电影。', 'The time expression appears before the action.'), exercise('Add “tomorrow” to 她在学校看书.', '她明天在学校看书。', 'The time phrase comes before the place and action.')]),
    point('G31', 'Distinguish before and ago with 前', 'time point + 前; duration + 前', '前 after a time point means before that point. After a duration, it can mean that amount of time ago, measured from the relevant reference time. The context determines the reference. Keep a time point, such as 八点, distinct from a duration, such as 三天. 前 also has a spatial use, but this point focuses on time.', [example('我八点前去学校。', 'Wǒ bā diǎn qián qù xué xiào.', 'I go to school before eight.'), example('我三天前在北京。', 'Wǒ sān tiān qián zài Běi jīng.', 'I was in Beijing three days ago.')], 'Do not translate 三天前 as “before three o’clock.” 三天 is a duration in days, not a clock time.', [exercise('Build “before ten o’clock.”', '十点前', '前 follows the time point.'), exercise('What does 五分钟前 mean?', 'Five minutes ago.', 'A duration followed by 前 refers backward from a reference time.')]),
  ]),
  unit(12, 'Conditions, descriptions, and predictions', 'Ask how something is, shorten close relationship phrases, and discuss degree and likelihood.', [
    point('G32', 'Ask about a condition with 怎么样', 'topic + 怎么样？', '怎么样 asks how something is or what someone thinks of it. It can ask about weather, a person’s condition, or the quality of an item. The answer usually supplies a description. Distinguish this from 怎么 + verb, which asks how an action is done. A topic and 怎么样 can form a complete beginner question.', [example('今天天气怎么样？', 'Jīn tiān tiān qì zěn me yàng?', 'What is the weather like today?'), example('这本书怎么样？', 'Zhè běn shū zěn me yàng?', 'What is this book like?')], 'Do not use 怎么写 and 怎么样 interchangeably. One asks the method of writing; the other asks for an evaluation or condition.', [exercise('Ask about the weather tomorrow.', '明天天气怎么样？', 'The weather is the topic being evaluated.'), exercise('Choose 怎么 or 怎么样 to ask how to pronounce a character.', '这个字怎么读？', 'This is a method question about 读, not an evaluation.')]),
    point('G33', 'Omit 的 in familiar close relationships', 'pronoun + close relative / familiar institution', 'In close family relationships and some familiar affiliation expressions, 的 is often omitted: 我妈妈, 你爸爸, 我们学校. Keeping 的 is also possible in many contexts, particularly with contrast or emphasis. This is a limited pattern, not a rule allowing every owner phrase to lose 的. For an ordinary owned object such as a book, retain 的 while learning.', [example('我妈妈是老师。', 'Wǒ mā ma shì lǎo shī.', 'My mother is a teacher.'), example('我们学校很大。', 'Wǒ men xué xiào hěn dà.', 'Our school is big.')], 'Do not generalize the family pattern to an ordinary owned object and write 我书 as your standard form for “my book.” Use 我的书.', [exercise('Shorten 我的爸爸 using the close-family pattern.', '我爸爸', 'The relationship is close and conventional, so 的 may be omitted.'), exercise('Should a beginner normally shorten 我的电脑 to 我电脑?', 'No. Keep 我的电脑 for the ordinary possession phrase.', 'The omission rule is limited and context dependent.')]),
    point('G34', 'Express a strong degree with 太…了', '太 + adjective + 了', '太…了 expresses a high degree, often a speaker’s strong reaction. Depending on context, it can be positive, as in “really good,” or negative, as in “too hot.” The final 了 belongs to this common expressive frame; it does not automatically place the description in the past. Do not add 很 before the same adjective in this pattern.', [example('今天太热了。', 'Jīn tiān tài rè le.', 'It is too hot today.'), example('太好了！', 'Tài hǎo le!', 'That is great!')], 'Avoid 太很好了. 太 and 很 do not stack in this simple degree frame. Translate the speaker’s reaction rather than mechanically making every 太 negative.', [exercise('React that this cup is too small.', '这个杯子太小了。', 'Use 太 + adjective + 了.'), exercise('Does 太好了 normally mean “It was too good”?', 'No. It commonly means “Great!” or “That is really good!”', 'The frame expresses a strong reaction rather than a past tense.')]),
    point('G35', 'Predict an event with 会', 'subject + 会 / 不会 + action or situation', '会 can express an expected or likely event, not only a learned skill. A future time or a weather context often makes this predictive meaning clear. The action itself does not need a tense ending. A future event can also be stated without 会 when other information makes the time clear; 会 adds a prediction or expectation.', [example('明天会下雨。', 'Míng tiān huì xià yǔ.', 'It will probably rain tomorrow.'), example('他下午会来。', 'Tā xià wǔ huì lái.', 'He is expected to come this afternoon.')], 'Do not interpret 会下雨 as a learned ability to rain. Choose the meaning of 会 from its context.', [exercise('Predict that it will not rain tomorrow.', '明天不会下雨。', '不会 negates the predicted event.'), exercise('Explain the two readings: 我会做饭 and 明天会下雨.', 'The first is a learned skill; the second is a prediction.', 'The same modal verb has different uses in different contexts.')]),
  ]),
  unit(13, 'Current actions and short requests', 'Recognize a telephone opening, describe an ongoing action, read phone numbers, and soften a request.', [
    point('G36', 'Recognize 喂 as a telephone opening', '喂，…', '喂 is a conventional call-opening interjection. It is not a verb meaning “to telephone,” and it is not automatically an appropriate way to address a teacher or stranger face to face. On the telephone, 喂 with fourth tone is a common neutral opening; tone and intonation can change the social effect. The word is included here as a pragmatic language point rather than a sentence-building rule.', [example('喂，你好。', 'Wèi, nǐ hǎo.', 'Hello. [answering a phone]'), example('喂，是王老师吗？', 'Wèi, shì Wáng lǎo shī ma?', 'Hello, is that Teacher Wang?')], 'Do not treat 喂 as a respectful general substitute for someone’s name. It is context sensitive.', [exercise('Which expression is a conventional telephone opening: 喂 or 再见?', '喂', '再见 closes an encounter rather than opening a call.'), exercise('Is 喂 a verb meaning “make a phone call”?', 'No. 打电话 is the ordinary verb phrase for making a call.', '喂 functions as an interjection in this lesson.')]),
    point('G37', 'Describe an action in progress with 在', 'subject + 在 + action (+ 呢)', '在 before an action can show that it is happening at the relevant moment. Sentence-final 呢 can reinforce that ongoing situation. Compare this with 在 + place: a place expression locates someone, while 在 followed directly by an activity can mark the action in progress. Not every verb naturally describes an ongoing activity. Negate an ongoing activity with 没 or 没有 before the action, often omitting 在.', [example('我在看书呢。', 'Wǒ zài kàn shū ne.', 'I am reading.'), example('她在喝茶。', 'Tā zài hē chá.', 'She is drinking tea.')], 'Do not use 正在 or 在 mechanically with every stative verb. For example, basic possession is 有, not 在有. Do not confuse 我在家 with an ongoing-action sentence.', [exercise('Make 他写字 describe an action happening now.', '他在写字。 / 他在写字呢。', '在 marks the activity as in progress.'), exercise('Distinguish 她在学校 and 她在看书.', 'The first locates her at school; the second describes her reading in progress.', 'The element after 在 determines its role in these beginner patterns.')]),
    point('G38', 'Read a telephone number digit by digit', 'one digit at a time; telephone 一 often read 幺', 'Read a telephone number as a sequence of digits rather than as one large counting number. 零 represents zero, and 二 remains 二 rather than becoming 两. In telephone numbers, 一 is often pronounced yāo to improve clarity; yī is also understood. This point is about reading numeric information rather than a new word-order rule.', [example('我的电话是三五六八。', 'Wǒ de diàn huà shì sān wǔ liù bā.', 'My phone number is 3568. [short practice number]'), example('一零二', 'yāo líng èr', '102, read as a telephone-style digit sequence')], 'Do not pronounce a phone digit 2 as 两 just because 两 is used before many measure words. Phone digits are read individually.', [exercise('Read the practice digit sequence 4062.', 'sì líng liù èr', 'Read each digit separately.'), exercise('What is the clearer alternate telephone reading of 一?', '幺, pronounced yāo.', 'It is commonly used to reduce confusion in spoken numbers.')]),
    point('G39', 'Soften a suggestion or instruction with 吧', 'suggestion/request + 吧', '吧 can soften an instruction, invitation, or suggestion. It often makes an action sound like a proposal instead of a blunt command. In this unit, learn the request/suggestion use rather than treating 吧 as a universal yes/no question ending. Context and intonation still matter for politeness.', [example('我们去学校吧。', 'Wǒ men qù xué xiào ba.', 'Let’s go to school.'), example('请坐吧。', 'Qǐng zuò ba.', 'Please, have a seat.')], 'Do not replace 吗 with 吧 in every yes/no question. A suggestion and a neutral request for information are not the same speech act.', [exercise('Suggest “Let’s drink some tea.”', '我们喝茶吧。', 'Final 吧 presents the action as a suggestion.'), exercise('Which is a neutral identity question: 你是老师吗 or 你是老师吧?', '你是老师吗？', '吗 asks neutrally; 吧 can suggest an assumption or another stance in other contexts.')]),
  ]),
  unit(14, 'Completed actions, sequencing, and everyone', 'Report a completed action, place events after a time, express a reaction, and include a whole group.', [
    point('G40', 'Present a completed action with 了', 'subject + verb + 了 + object', '了 after a verb can present an action as completed. It marks aspect, not a general past tense: a past habitual action need not use 了, and a completed action can be discussed in other time frames. A specific object quantity often makes a simple completed-action sentence clearer. Negate an action that has not happened with 没 or 没有 and normally remove this completed-action 了.', [example('我买了三个苹果。', 'Wǒ mǎi le sān ge píng guǒ.', 'I bought three apples.'), example('她喝了一杯水。', 'Tā hē le yì bēi shuǐ.', 'She drank a glass of water.')], 'Avoid 我没买了书 for the ordinary negative “I did not buy a book.” Use 我没买书. Distinguish completed-action 了 from the change-of-state use introduced earlier.', [exercise('Report completing “write three characters.”', '我写了三个字。', 'Place 了 after the action verb and before the quantified object.'), exercise('Negate 他买了一本书 as “He did not buy a book.”', '他没买书。 / 他没有买书。', '没/没有 negates the event; ordinary completed-action 了 is removed.')]),
    point('G41', 'Express after or later with 后', 'time point + 后; duration + 后', '后 after a time point means after that point. After a duration, it means that amount of time later, measured from the reference supplied by context. The contrast with 前 is useful: 三天前 looks backward, while 三天后 looks forward. 后 does not by itself guarantee that the reference time is the present.', [example('我十点后回家。', 'Wǒ shí diǎn hòu huí jiā.', 'I go home after ten.'), example('我们两天后去北京。', 'Wǒ men liǎng tiān hòu qù Běi jīng.', 'We go to Beijing two days later / in two days.')], 'Do not confuse duration + 后 with a clock time. 两天后 is not “after two o’clock.”', [exercise('Build “after three o’clock.”', '三点后', '后 follows the time point.'), exercise('Contrast 两天前 and 两天后.', 'Two days before/ago versus two days later/in two days.', 'The reference time is determined by context.')]),
    point('G42', 'Recognize an expressive final 啊', 'remark or description + 啊', '啊 can add an expressive, responsive, or exclamatory tone. Its effect depends on the speaker and context; it is not a past-tense marker or a word that always translates as “ah.” For beginners, recognize it in an expressive remark and keep the underlying sentence understandable without it. Spoken pronunciation may adjust after the preceding sound.', [example('这个杯子真好啊！', 'Zhè ge bēi zi zhēn hǎo a!', 'What a nice cup!'), example('今天很热啊！', 'Jīn tiān hěn rè a!', 'It really is hot today!')], 'Do not attach 啊 to every statement. Its use conveys the speaker’s tone, and a plain sentence without it is often more neutral.', [exercise('Remove the expressive particle from 今天很冷啊.', '今天很冷。', 'The descriptive content remains after 啊 is removed.'), exercise('Does final 啊 automatically make a sentence past tense?', 'No.', 'It adds an expressive or interactional tone, not a tense ending.')]),
    point('G43', 'Include a whole group with 都', 'group subject + 都 + predicate', '都 normally comes after the group it refers to and before the predicate. It can mean “all” or “both,” depending on the group. Its position is important: 我们都是学生 means all of us are students. 都不 makes the negative apply across the group; 不都 means not all, so the two orders do not express the same thing.', [example('我们都是学生。', 'Wǒ men dōu shì xué sheng.', 'We are all students.'), example('爸爸和妈妈都在家。', 'Bà ba hé mā ma dōu zài jiā.', 'Both father and mother are at home.')], 'Do not put 都 before the group subject in the basic pattern. Keep the difference between 都不, “none do,” and 不都, “not all do.”', [exercise('Say “Both of us drink tea.”', '我们两个都喝茶。 / 我们都喝茶。', '都 follows the group subject.'), exercise('Which means not all: 都不 or 不都?', '不都', 'The negative scopes over “all,” rather than applying to every group member.')]),
  ]),
  unit(15, 'Emphasizing event details and full dates', 'Highlight how, when, or where an established event happened, then combine a full calendar date.', [
    point('G44', 'Highlight a known event’s details with 是…的', 'subject + 是 + time/place/manner + verb (+ object) + 的', 'Use this frame when the event is already treated as established and the focus is a detail such as its time, place, or manner. The purpose is not simply to say that an event happened. 是 may be omitted in suitable affirmative contexts, but keep the full frame while learning. To deny a highlighted detail in the standard frame, use 不是…的 rather than treating it like ordinary 没 + verb negation.', [example('我是昨天来的。', 'Wǒ shì zuó tiān lái de.', 'It was yesterday that I came.'), example('她是坐出租车来的。', 'Tā shì zuò chū zū chē lái de.', 'She came by taxi. [The manner is emphasized.]')], 'Do not use 是…的 as a universal past-tense form. Contrast reporting a purchase with 买了 and emphasizing how a known arrival happened with 是…来的.', [exercise('Emphasize that you came in the morning.', '我是上午来的。', 'The arrival is established; 上午 is the highlighted detail.'), exercise('Deny “I came by airplane” while preserving the event-detail frame.', '我不是坐飞机来的。', '不是 negates the highlighted manner within 是…的.')]),
    point('G45', 'Combine a year, month, day, and weekday', 'year + 年 + month + 月 + day + 日/号 (+ weekday)', 'A full calendar date runs from the largest unit to the smallest: year, month, then day. Read an ordinary four-digit year digit by digit rather than as a large counting number. A weekday can follow the date. Distinguish this from reading a quantity such as two thousand, which uses the ordinary counting system. Dates can serve as time phrases before an action.', [example('二零二六年六月八号', 'èr líng èr liù nián liù yuè bā hào', 'June 8, 2026'), example('我五月三号去北京。', 'Wǒ wǔ yuè sān hào qù Běi jīng.', 'I am going to Beijing on May 3.')], 'Do not read the calendar year 2026 as 两千零二十六年 in the ordinary date-reading pattern. Do not use English day–month order inside this Mandarin frame.', [exercise('Write March 12, 2025 in Chinese characters.', '二零二五年三月十二号 / 二零二五年三月十二日', 'Read the year by digits, then give the month and day.'), exercise('Put “on June 2” into 我去学校.', '我六月二号去学校。 / 六月二号我去学校。', 'The date is a time expression placed before the action.')]),
  ]),
];

const reviews = [
  { afterUnit: 5, title: 'Checkpoint 1: identity, questions, family, and numbers', passMark: 5, questions: [
    exercise('Arrange: 名字 / 什么 / 你 / 叫.', '你叫什么名字？', 'Keep statement order and put 什么 in the position of the unknown name.'),
    exercise('Translate “She is not a teacher.”', '她不是老师。', '不 negates 是.'),
    exercise('Ask “Whose book is this?”', '这是谁的书？', '谁 replaces the owner before 的.'),
    exercise('Respond “What about you?” after your partner gives their occupation.', '你呢？', 'The shared occupation topic supplies the omitted question.'),
    exercise('Write 67 and 76 in Chinese.', '六十七；七十六', 'The tens and ones occupy different positions.'),
    exercise('Give the age of a six-year-old and highlight reaching that age.', '他六岁了。 / 她六岁了。', '岁 expresses age and final 了 highlights the new state.'),
  ] },
  { afterUnit: 10, title: 'Checkpoint 2: skills, dates, quantity, and location', passMark: 5, questions: [
    exercise('Say “I know how to write Chinese characters.”', '我会写汉字。', '会 describes a learned skill.'),
    exercise('Say “Today is Thursday” without 是.', '今天星期四。', 'A weekday phrase can act as the predicate.'),
    exercise('Say “We go to the shop to buy apples.”', '我们去商店买苹果。', 'The destination is followed by the intended activity.'),
    exercise('Give “two cups” and ask their price.', '两个杯子。两个杯子多少钱？', 'Use 两 before 个 and 多少钱 for price.'),
    exercise('Say “The teacher reads at home.”', '老师在家看书。', 'The place phrase comes before the action.'),
    exercise('Politely ask whether you may sit here.', '我能坐这儿吗？ / 我能坐这里吗？', '能…吗 asks whether the action is allowed.'),
  ] },
  { afterUnit: 15, title: 'Checkpoint 3: time, current action, completion, and emphasis', passMark: 5, questions: [
    exercise('Say “We drink tea at three in the afternoon.”', '我们下午三点喝茶。', 'Put the time before the action.'),
    exercise('Ask what tomorrow’s weather will be like.', '明天天气怎么样？', '怎么样 asks for a condition or evaluation.'),
    exercise('Say “She is reading now.”', '她现在在看书。 / 她现在在看书呢。', '现在 gives the time and 在 marks the ongoing activity.'),
    exercise('Say “I bought two books,” then negate the event.', '我买了两本书。；我没买书。', 'Use completed-action 了 positively; use 没 and remove this 了 in the negative.'),
    exercise('Say “Both father and mother are at home.”', '爸爸和妈妈都在家。', '和 joins the nouns; 都 follows the combined subject.'),
    exercise('Emphasize that you arrived yesterday.', '我是昨天来的。', 'Use 是…的 to highlight the time of an established event.'),
  ] },
];

